// Stripe stores money in minor units. Turn it into a human-readable, VAT-inclusive receipt model.
const customer = $input.first().json;
const event = $('Stripe Payment Success Trigger').first().json;
const payment = event.data.object;

const currency = String(payment.currency || 'eur').toUpperCase();
const locale = customer.locale || 'en-GB';
const vatPercent = Number(customer.vat_percent ?? 19);
const gross = Math.round(Number(payment.amount_received ?? payment.amount ?? 0)) / 100;
const net = Math.round((gross / (1 + vatPercent / 100)) * 100) / 100;
const vat = Math.round((gross - net) * 100) / 100;
const paidAt = new Date(Number(payment.created) * 1000);
const money = (value) => new Intl.NumberFormat(locale, { style: 'currency', currency }).format(value);
const address = customer.address || {};
const customerAddress = [address.line1, address.line2, [address.postal_code, address.city].filter(Boolean).join(' '), address.country].filter(Boolean);
const lineItems = [{
  description: payment.description || 'Payment',
  quantity: 1,
  net,
  net_display: money(net),
  vat,
  vat_display: money(vat),
  gross,
  gross_display: money(gross),
}];
const esc = (value) => String(value ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' })[c]);
const rows = lineItems.map((line) => `<tr><td>${esc(line.description)}</td><td class=\"num\">${line.quantity}</td><td class=\"num\">${esc(line.net_display)}</td><td class=\"num\">${esc(line.vat_display)}</td><td class=\"num\">${esc(line.gross_display)}</td></tr>`).join('');
const receiptNumber = `RCPT-${paidAt.getUTCFullYear()}-${String(payment.id).replace(/^pi_/, '').slice(-10).toUpperCase()}`;
const dateDisplay = new Intl.DateTimeFormat(locale, { year: 'numeric', month: 'long', day: '2-digit', timeZone: 'UTC' }).format(paidAt);
const receiptHtml = `<!doctype html><html><head><meta charset=\"utf-8\"><style>
@page{size:A4;margin:18mm 16mm 20mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#172033;font-size:12px;margin:0}.top{display:flex;justify-content:space-between;border-bottom:4px solid #3157d5;padding-bottom:18px}.brand{font-size:25px;font-weight:700;color:#3157d5}.muted{color:#667085;line-height:1.55}.receipt{text-align:right}.receipt h1{font-size:28px;margin:0 0 8px}.parties{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin:28px 0}h2{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#667085}table{width:100%;border-collapse:collapse;margin-top:22px}th{text-align:left;background:#eef2ff;padding:10px 8px;border-bottom:2px solid #3157d5}td{padding:12px 8px;border-bottom:1px solid #d9deea}tr{break-inside:avoid}.num{text-align:right;white-space:nowrap}.totals{width:310px;margin:24px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px 8px}.totals .grand{font-size:17px;font-weight:700;border-top:2px solid #172033;margin-top:5px;padding-top:12px}.paid{display:inline-block;margin-top:18px;padding:7px 12px;background:#dcfae6;color:#087443;font-weight:700;border-radius:4px}.footer{position:fixed;bottom:0;left:0;right:0;border-top:1px solid #d9deea;padding-top:8px;font-size:10px;color:#667085}
</style></head><body><div class=\"top\"><div><div class=\"brand\">${esc(customer.seller_name)}</div><div class=\"muted\">${esc(customer.seller_address)}<br>VAT ID: ${esc(customer.seller_vat_id)}<br>${esc(customer.seller_email)}</div></div><div class=\"receipt\"><h1>Receipt</h1><strong>${esc(receiptNumber)}</strong><br><span class=\"muted\">${esc(dateDisplay)}</span><br><span class=\"paid\">PAID</span></div></div><div class=\"parties\"><div><h2>Received from</h2><strong>${esc(customer.name || 'Stripe customer')}</strong><div class=\"muted\">${customerAddress.map(esc).join('<br>')}<br>${esc(customer.email)}</div></div><div><h2>Payment details</h2><div class=\"muted\">Stripe payment ${esc(payment.id)}<br>Currency: ${esc(currency.toUpperCase())}</div></div></div><table><thead><tr><th>Description</th><th class=\"num\">Qty</th><th class=\"num\">Net</th><th class=\"num\">VAT</th><th class=\"num\">Gross</th></tr></thead><tbody>${rows}</tbody></table><div class=\"totals\"><div><span>Net</span><span>${esc(money(net))}</span></div><div><span>VAT ${vatPercent}%</span><span>${esc(money(vat))}</span></div><div class=\"grand\"><span>Total paid</span><span>${esc(money(gross))}</span></div></div><div class=\"footer\">${esc(customer.footer_note)}</div></body></html>`;

return [{ json: {
  receipt_number: receiptNumber,
  receipt_date: dateDisplay,
  payment_intent_id: payment.id,
  customer_name: customer.name || 'Stripe customer',
  customer_email: customer.email || '',
  customer_address: customerAddress,
  currency,
  line_items: lineItems,
  net, net_display: money(net),
  vat_percent: vatPercent, vat, vat_display: money(vat),
  gross, gross_display: money(gross),
  receipt_html: receiptHtml,
  archive_file_name: `${receiptNumber}.pdf`,
} }];
